function cn(...parts: Array<string | false | undefined>) { return parts.filter(Boolean).join(' '); }
function dateLabel(value?: string) {
  if (!value) return '—';
  return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value));
}
function riskClass(level?: string) {
  return level === RiskLevel.HIGH ? 'text-[#ff756b] bg-[#ff756b]/10 border-[#ff756b]/25' :
    level === RiskLevel.MEDIUM ? 'text-[#f4bf48] bg-[#f4bf48]/10 border-[#f4bf48]/25' :
      'text-[#5ed9ad] bg-[#5ed9ad]/10 border-[#5ed9ad]/25';
}
function statusClass(status?: string) {
  return status === 'RESOLVED' ? 'text-[#5ed9ad] bg-[#5ed9ad]/10 border-[#5ed9ad]/25' :
    status === 'REJECTED' ? 'text-[#ff756b] bg-[#ff756b]/10 border-[#ff756b]/25' :
      'text-[#f4bf48] bg-[#f4bf48]/10 border-[#f4bf48]/25';
}

function Badge({ children, className = '' }: { children: React.ReactNode; className?: string }) {
  return <span className={cn('inline-flex items-center rounded-full border px-2 py-0.5 text-[10px] font-mono uppercase tracking-[.08em]', className)}>{children}</span>;
}
function Button({ children, className = '', variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'danger' }) {
  return <button {...props} className={cn(
    'inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-xs font-semibold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50',
    variant === 'primary' && 'bg-[#f4bf48] text-[#16150e] hover:bg-[#ffd46d] active:scale-[.98]',
    variant === 'ghost' && 'border border-[#263446] bg-[#111b28] text-[#c0cad5] hover:border-[#f4bf48]/45 hover:text-[#f8f4ea]',
    variant === 'danger' && 'border border-[#ff756b]/30 bg-[#ff756b]/10 text-[#ff9a92] hover:bg-[#ff756b]/20',
    className,
  )}>{children}</button>;
}
function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
    <div><div className="mb-2 flex items-center gap-2 text-[10px] font-mono uppercase tracking-[.22em] text-[#76879a]"><span className="h-1.5 w-1.5 rounded-full bg-[#f4bf48]" />{eyebrow}</div><h1 className="text-2xl font-extrabold tracking-[-.04em] text-[#f8f4ea] sm:text-3xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#8593a3]">{description}</p>}</div>
    {action}
  </div>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={cn('animate-pulse rounded-lg bg-[#152131]', className)} />; }
function QueryState({ loading, error, onRetry, children }: { loading?: boolean; error?: boolean; onRetry?: () => void; children: React.ReactNode }) {
  if (loading) return <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Skeleton className="h-32" /><Skeleton className="h-32" /><Skeleton className="h-32" /><Skeleton className="h-32" /></div>;
  if (error) return <div className="rounded-xl border border-[#ff756b]/25 bg-[#ff756b]/5 p-8 text-center"><AlertTriangle className="mx-auto mb-3 text-[#ff756b]" size={22} /><p className="text-sm text-[#ffb0a9]">The operations feed could not be reached.</p><Button variant="ghost" className="mt-4" onClick={onRetry}><RefreshCw size={14} />Try again</Button></div>;
  return <>{children}</>;
}

