function StatCard({ label, value, detail, tone = 'gold', icon: Icon }: { label: string; value: string | number; detail: string; tone?: string; icon: React.ElementType }) {
  const colors: Record<string, string> = { gold: 'text-[#f4bf48] bg-[#f4bf48]/10', red: 'text-[#ff756b] bg-[#ff756b]/10', amber: 'text-[#f4bf48] bg-[#f4bf48]/10', green: 'text-[#5ed9ad] bg-[#5ed9ad]/10' };
  return <div className="animate-rise rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-4 sm:p-5" data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><div><p className="text-[10px] font-mono uppercase tracking-[.14em] text-[#718197]">{label}</p><p className="mt-3 text-3xl font-extrabold tracking-[-.05em] text-[#f8f4ea]">{value}</p></div><span className={cn('rounded-lg p-2', colors[tone])}><Icon size={17} /></span></div><p className="mt-4 text-[11px] text-[#718197]">{detail}</p></div>;
}
function HazardRow({ hazard, onSelect }: { hazard: Hazard; onSelect?: (hazard: Hazard) => void }) {
  return <button onClick={() => onSelect?.(hazard)} className="group grid w-full grid-cols-[1fr_auto] gap-4 border-b border-[#1d2b3b] py-4 text-left last:border-0 hover:bg-[#111c29] sm:grid-cols-[1.3fr_1fr_auto_auto]" data-testid={`row-hazard-${hazard.id}`}><div className="min-w-0"><div className="mb-1 flex items-center gap-2"><span className="truncate text-sm font-semibold text-[#e9edf0]">{hazard.hazardType}</span><Badge className={riskClass(hazard.riskLevel)}>{hazard.riskLevel}</Badge></div><p className="flex items-center gap-1 truncate text-xs text-[#74869a]"><MapPin size={12} />{hazard.location}</p></div><div className="hidden items-center gap-2 sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-[#5ed9ad]" /><span className="text-xs text-[#a0adba]">{hazard.status.replace('_', ' ')}</span></div><span className="hidden text-xs text-[#718197] sm:block">{dateLabel(hazard.createdAt)}</span><span className="self-center text-[#6d7e90] transition-transform group-hover:translate-x-1"><ArrowUpRight size={16} /></span></button>;
}

