  return <><SectionHeading eyebrow="Live overview" title="Road safety, at a glance" description="A single operating picture for hazards reported across your jurisdiction." action={<Link href="/analyze" className="inline-flex items-center justify-center gap-2 rounded-lg bg-[#f4bf48] px-4 py-2.5 text-xs font-bold text-[#16150e] hover:bg-[#ffd46d]" data-testid="link-log-hazard"><Crosshair size={15} />Log a hazard</Link>} />
   <QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{summary && <><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><StatCard label="Total records" value={summary.totalRecords} detail="Saved hazard observations" icon={Layers3} /><StatCard label="High risk" value={summary.highRisk} detail="Require urgent attention" tone="red" icon={Siren} /><StatCard label="Medium risk" value={summary.mediumRisk} detail="Monitor and schedule" tone="amber" icon={AlertTriangle} /><StatCard label="Low risk" value={summary.lowRisk} detail="Track and monitor" tone="green" icon={Check} /></div>
      <div className="mt-6 grid gap-6 xl:grid-cols-[1fr_340px]"><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5 sm:p-6"><div className="mb-2 flex items-center justify-between"><div><h2 className="text-base font-bold text-[#f2f0e9]">Recent hazards</h2><p className="mt-1 text-xs text-[#718197]">The latest signals entering the network.</p></div><Link href="/map" className="text-xs font-semibold text-[#f4bf48] hover:text-[#ffdb81]" data-testid="link-view-all-hazards">View all <ArrowUpRight className="ml-1 inline" size={13} /></Link></div><div className="mt-3">{summary.recentHazards.length ? summary.recentHazards.map(h => <HazardRow key={h.id} hazard={h} onSelect={setSelected} />) : <EmptyState icon={Navigation} title="No hazard records yet" description="Analyze a road image to create the first signal." action={<Link href="/analyze" className="text-xs font-bold text-[#f4bf48]" data-testid="link-empty-analyze">Start an analysis</Link>} />}</div></div><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5 sm:p-6"><div className="mb-5 flex items-center gap-3"><span className="rounded-lg bg-[#f4bf48]/10 p-2 text-[#f4bf48]"><Activity size={17} /></span><div><h2 className="text-base font-bold text-[#f2f0e9]">Network pulse</h2><p className="text-xs text-[#718197]">Current response posture</p></div></div><div className="relative mb-5 h-24 overflow-hidden rounded-lg border border-[#203044] bg-[#0b131e]"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: 'linear-gradient(90deg, transparent 49%, #27384b 50%, transparent 51%),linear-gradient(#27384b 1px,transparent 1px)', backgroundSize: '44px 44px' }} /><div className="absolute left-[28%] top-[42%] h-2 w-2 rounded-full bg-[#ff756b] shadow-[0_0_0_7px_rgba(255,117,107,.12)]" /><div className="absolute left-[69%] top-[58%] h-2 w-2 rounded-full bg-[#f4bf48] shadow-[0_0_0_7px_rgba(244,191,72,.12)]" /><div className="absolute left-[51%] top-[24%] h-2 w-2 rounded-full bg-[#5ed9ad] shadow-[0_0_0_7px_rgba(94,217,173,.12)]" /></div><div className="space-y-3"><div className="flex justify-between text-xs"><span className="text-[#8291a1]">Network coverage</span><span className="font-mono text-[#d9e0e6]">{summary.totalRecords ? 'Active' : 'Awaiting data'}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-[#1b2a3a]"><div className="h-full w-[76%] rounded-full bg-[#f4bf48]" /></div><div className="flex items-center gap-2 text-[11px] text-[#718197]"><span className="h-1.5 w-1.5 rounded-full bg-[#5ed9ad]" />Operating normally across monitored zones</div></div></div></div></>}</QueryState>
    {selected && <HazardDrawer hazard={selected} onClose={() => setSelected(null)} />}
  </>;
