function EmptyState({ icon: Icon, title, description, action }: { icon: React.ElementType; title: string; description: string; action?: React.ReactNode }) {
  return <div className="py-12 text-center"><Icon className="mx-auto mb-3 text-[#506174]" size={24} /><h3 className="text-sm font-semibold text-[#dce2e7]">{title}</h3><p className="mx-auto mt-1 max-w-xs text-xs leading-5 text-[#718197]">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function HazardDrawer({ hazard, onClose }: { hazard: Hazard; onClose: () => void }) {
  const update = useUpdateHazard();
  const remove = useDeleteHazard();
  const qc = useQueryClient();
  const changeStatus = (status: HazardStatus) => update.mutate({ id: hazard.id, data: { status } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetHazardsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); onClose(); } });
  return <div className="fixed inset-0 z-50 flex justify-end bg-[#02060b]/60" onClick={onClose}><section className="h-full w-full max-w-md overflow-y-auto border-l border-[#263749] bg-[#0d1723] p-6 shadow-2xl" onClick={e => e.stopPropagation()}><div className="mb-8 flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#718197]">Hazard record / {hazard.id}</p><h2 className="mt-2 text-xl font-bold text-[#f8f4ea]">{hazard.hazardType}</h2></div><button onClick={onClose} className="rounded-lg p-2 text-[#8493a3] hover:bg-[#172636]" data-testid="button-close-hazard"><X size={18} /></button></div><div className="space-y-5"><div className="flex gap-2"><Badge className={riskClass(hazard.riskLevel)}>{hazard.riskLevel} · {hazard.riskScore}/100</Badge><Badge className={statusClass(hazard.status)}>{hazard.status.replace('_', ' ')}</Badge></div><div className="rounded-lg border border-[#203144] bg-[#111d2b] p-4"><div className="flex items-center gap-2 text-xs text-[#8c9bad]"><MapPin size={14} className="text-[#f4bf48]" />{hazard.location}</div><p className="mt-4 text-sm leading-6 text-[#bec9d4]">{hazard.description}</p></div><Detail label="Recommended action" value={hazard.recommendedAction} /><Detail label="Responsible authority" value={hazard.responsibleAuthority} /><Detail label="Damage estimate" value={`${hazard.damagePercentage}% surface damage`} /><Detail label="Recorded" value={dateLabel(hazard.createdAt)} /><div className="border-t border-[#203144] pt-5"><p className="mb-3 text-[10px] font-mono uppercase tracking-[.16em] text-[#718197]">Update status</p><div className="grid grid-cols-3 gap-2">{[HazardStatus.OPEN, HazardStatus.IN_PROGRESS, HazardStatus.RESOLVED].map(status => <button key={status} disabled={update.isPending} onClick={() => changeStatus(status)} className={cn('rounded-lg border px-2 py-2 text-[10px] font-bold uppercase tracking-wide transition-colors', hazard.status === status ? statusClass(status) : 'border-[#243547] text-[#8493a3] hover:border-[#f4bf48]/40')} data-testid={`button-status-${status.toLowerCase()}`}>{status.replace('_', ' ')}</button>)}</div></div><Button variant="danger" className="w-full" disabled={remove.isPending} onClick={() => { if (window.confirm('Delete this hazard record?')) remove.mutate({ id: hazard.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetHazardsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); onClose(); } }); }} data-testid="button-delete-hazard"><Trash2 size={14} />Delete record</Button></div></section></div>;
}
function Detail({ label, value }: { label: string; value: string }) { return <div><p className="mb-1 text-[10px] font-mono uppercase tracking-[.13em] text-[#718197]">{label}</p><p className="text-sm leading-5 text-[#d5dde4]">{value}</p></div>; }

function Analyze() {
  const [imageUrl, setImageUrl] = useState('');
  const [location, setLocation] = useState('');
  const [hazardType, setHazardType] = useState<string>('');
  const [latitude, setLatitude] = useState<number>();
  const [longitude, setLongitude] = useState<number>();
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [saved, setSaved] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const analyze = useAnalyzeRoad();
  const create = useCreateHazard();
  const qc = useQueryClient();
  const onFile = (file?: File) => { if (!file) return; if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type) || file.size > 8 * 1024 * 1024) { window.alert('Choose a JPG, PNG, or WEBP image smaller than 8 MB.'); return; } const reader = new FileReader(); reader.onload = () => setImageUrl(String(reader.result)); reader.readAsDataURL(file); };
  const useLocation = () => navigator.geolocation?.getCurrentPosition(({ coords }) => { setLatitude(coords.latitude); setLongitude(coords.longitude); }, () => window.alert('Location permission was not granted. You can continue with a manual location.'));
  const run = () => analyze.mutate({ data: { imageUrl, location: location || undefined, hazardType: hazardType ? hazardType as typeof HazardType[keyof typeof HazardType] : undefined } }, { onSuccess: setResult });
  const save = () => { if (!result) return; const payload: HazardInput = { hazardType: result.detectedHazard, location: location || 'Location not provided', latitude, longitude, imageUrl: imageUrl || undefined, damagePercentage: result.damagePercentage, riskScore: result.riskScore, description: result.description, recommendedAction: result.recommendedAction, responsibleAuthority: Authority.Local_Road_Authority }; create.mutate({ data: payload }, { onSuccess: () => { setSaved(true); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetHazardsQueryKey() }); qc.invalidateQueries({ queryKey: getGetReportsQueryKey() }); } }); };
  return <><SectionHeading eyebrow="Development analysis" title="Turn a road image into a signal" description="Upload a field image. RoadGuard will classify the visible hazard, estimate damage, and recommend the next operational move." /><div className="grid gap-6 xl:grid-cols-[1.05fr_.95fr]"><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5 sm:p-7"><div className="mb-6 flex items-center justify-between"><div><h2 className="text-base font-bold text-[#f2f0e9]">Capture evidence</h2><p className="mt-1 text-xs text-[#718197]">JPG, PNG, or WEBP · one clear road view</p></div><Badge className="border-[#2a3d51] text-[#8091a4]"><LockKeyhole size={11} className="mr-1" />Private by default</Badge></div><button onClick={() => fileRef.current?.click()} className={cn('group relative flex min-h-[275px] w-full items-center justify-center overflow-hidden rounded-xl border border-dashed transition-colors', imageUrl ? 'border-[#f4bf48]/40 bg-[#0a111a]' : 'border-[#304257] bg-[#0b141f] hover:border-[#f4bf48]/60')} data-testid="button-upload-image">{imageUrl ? <><img src={imageUrl} alt="Selected road evidence" className="absolute inset-0 h-full w-full object-cover opacity-70" /><div className="absolute inset-0 bg-[#07101a]/45" /><div className="relative rounded-lg bg-[#0d1723]/90 px-4 py-3 text-xs text-[#f8f4ea]"><Upload size={15} className="mr-2 inline text-[#f4bf48]" />Replace image</div></> : <div className="text-center"><span className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-xl bg-[#f4bf48]/10 text-[#f4bf48]"><Camera size={22} /></span><p className="text-sm font-semibold text-[#e6ebee]">Drop a road image here</p><p className="mt-1 text-xs text-[#718197]">or choose a file from this device</p></div>}</button><input ref={fileRef} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={e => onFile(e.target.files?.[0])} data-testid="input-road-image" /><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#9cabb9]">Location<span className="mt-2 block"><input value={location} onChange={e => setLocation(e.target.value)} placeholder="e.g. 14th Street & Pine Avenue" className="w-full rounded-lg border border-[#293b4e] bg-[#0b141e] px-3 py-2.5 text-sm font-normal text-[#edf1f3] outline-none placeholder:text-[#526478] focus:border-[#f4bf48]/60" data-testid="input-analysis-location" /></span></label><label className="text-xs font-semibold text-[#9cabb9]">Optional classification<span className="mt-2 block"><select value={hazardType} onChange={e => setHazardType(e.target.value)} className="w-full rounded-lg border border-[#293b4e] bg-[#0b141e] px-3 py-2.5 text-sm font-normal text-[#edf1f3] outline-none focus:border-[#f4bf48]/60" data-testid="select-analysis-type"><option value="">Let analysis decide</option>{hazardTypes.map(t => <option key={t} value={t}>{t}</option>)}</select></span></label></div><button type="button" onClick={useLocation} className="mt-3 text-xs font-semibold text-[#f4bf48] hover:text-[#ffdb81]" data-testid="button-use-location"><Navigation size={13} className="mr-1 inline" />Use my location{latitude != null && longitude != null ? ` · ${latitude.toFixed(3)}, ${longitude.toFixed(3)}` : ''}</button><Button className="mt-6 w-full py-3" disabled={!imageUrl || analyze.isPending} onClick={run} data-testid="button-run-analysis">{analyze.isPending ? <><Loader2 size={15} className="animate-spin" />Analyzing evidence</> : <><Zap size={15} />Run development analysis</>}</Button>{analyze.isError && <p className="mt-3 text-center text-xs text-[#ff9188]">Analysis failed. Check the image and try again.</p>}</div><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5 sm:p-7"><div className="mb-6 flex items-center gap-3"><span className="rounded-lg bg-[#197b91]/15 p-2 text-[#57c7d8]"><Activity size={17} /></span><div><h2 className="text-base font-bold text-[#f2f0e9]">Analysis output</h2><p className="mt-1 text-xs text-[#718197]">Decision support, not a final inspection</p></div></div>{!result && !analyze.isPending && <EmptyState icon={Crosshair} title="Awaiting evidence" description="Upload an image and run the analysis to see a structured hazard assessment here." />}{analyze.isPending && <div className="relative flex min-h-[310px] items-center justify-center overflow-hidden rounded-xl border border-[#26394d] bg-[#0a131d]"><div className="absolute inset-x-0 top-0 h-px bg-[#f4bf48] shadow-[0_0_18px_rgba(244,191,72,.8)] scan-line" /><div className="text-center"><div className="mx-auto mb-4 h-12 w-12 rounded-full border-2 border-[#f4bf48]/20 border-t-[#f4bf48] animate-spin" /><p className="text-sm font-semibold text-[#e9edf0]">Reading road conditions</p><p className="mt-2 text-xs text-[#718197]">Classifying visible damage and risk</p></div></div>}{result && <div className="animate-rise"><div className="mb-5 flex items-center justify-between"><Badge className={riskClass(result.riskLevel)}>{result.riskLevel} risk</Badge><span className="font-mono text-[10px] uppercase tracking-wide text-[#718197]">{result.source.replace('_', ' ')}</span></div><div className="grid grid-cols-2 gap-3"><div className="rounded-lg border border-[#26394d] bg-[#111e2c] p-4"><p className="text-[10px] font-mono uppercase tracking-wide text-[#718197]">Detected hazard</p><p className="mt-2 text-lg font-bold text-[#f4bf48]">{result.detectedHazard}</p></div><div className="rounded-lg border border-[#26394d] bg-[#111e2c] p-4"><p className="text-[10px] font-mono uppercase tracking-wide text-[#718197]">Risk score</p><p className="mt-2 text-lg font-bold text-[#f8f4ea]">{result.riskScore}<span className="text-xs font-normal text-[#718197]"> / 100</span></p></div></div><div className="mt-4 space-y-4"><Detail label="Observed condition" value={result.description} /><Detail label="Recommended action" value={result.recommendedAction} /><div><div className="mb-2 flex justify-between text-[10px] font-mono uppercase tracking-wide text-[#718197]"><span>Estimated surface damage</span><span className="text-[#dbe3e8]">{result.damagePercentage}%</span></div><div className="h-2 rounded-full bg-[#1b2a3a]"><div className="h-full rounded-full bg-[#f4bf48]" style={{ width: `${result.damagePercentage}%` }} /></div></div></div>{saved ? <div className="mt-6 flex items-center gap-2 rounded-lg border border-[#5ed9ad]/25 bg-[#5ed9ad]/10 px-3 py-3 text-xs font-semibold text-[#75e5ba]"><Check size={15} />Hazard saved to the operations feed</div> : <Button className="mt-6 w-full" disabled={create.isPending} onClick={save} data-testid="button-save-hazard">{create.isPending ? <Loader2 size={15} className="animate-spin" /> : <Shield size={15} />}Save hazard record</Button>}</div>}</div></div></>;
}

function MapPage() {
  const [risk, setRisk] = useState('');
  const [status, setStatus] = useState('');
  const [selected, setSelected] = useState<Hazard | null>(null);
  const params = { ...(risk ? { riskLevel: risk as RiskLevel } : {}), ...(status ? { status: status as HazardStatus } : {}) };
  const query = useGetHazards(params, { query: { queryKey: getGetHazardsQueryKey(params), refetchInterval: 60000 } });
  const hazards = query.data || [];
  return <><SectionHeading eyebrow="Geospatial operations" title="Risk map" description="Browse every saved signal, filter response posture, and open a record for action." action={<div className="flex gap-2"><select value={risk} onChange={e => setRisk(e.target.value)} className="rounded-lg border border-[#293b4e] bg-[#111c29] px-3 py-2 text-xs text-[#cdd6df] outline-none" data-testid="select-map-risk"><option value="">All risk</option>{Object.values(RiskLevel).map(v => <option key={v} value={v}>{v}</option>)}</select><select value={status} onChange={e => setStatus(e.target.value)} className="rounded-lg border border-[#293b4e] bg-[#111c29] px-3 py-2 text-xs text-[#cdd6df] outline-none" data-testid="select-map-status"><option value="">All status</option>{Object.values(HazardStatus).map(v => <option key={v} value={v}>{v.replace('_', ' ')}</option>)}</select></div>} /><QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{<div className="grid gap-6 xl:grid-cols-[1fr_360px]"><div className="relative min-h-[520px] overflow-hidden rounded-xl border border-[#1d2b3b] map-grid"><MapContainer center={[20.0, 73.9]} zoom={8} scrollWheelZoom className="h-[520px] w-full"><TileLayer attribution='&copy; OpenStreetMap contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />{hazards.filter(h => h.latitude != null && h.longitude != null).map(h => { const color = h.riskLevel === RiskLevel.HIGH ? '#ff756b' : h.riskLevel === RiskLevel.MEDIUM ? '#f4bf48' : '#5ed9ad'; return <CircleMarker key={h.id} center={[h.latitude!, h.longitude!]} radius={9} pathOptions={{ color, fillColor: color, fillOpacity: 0.85 }} eventHandlers={{ click: () => setSelected(h) }}><Popup><strong>{h.hazardType}</strong><br />{h.location}<br />{h.riskLevel} · {h.riskScore}/100</Popup></CircleMarker>; })}</MapContainer><div className="absolute left-5 top-5 z-[400] flex items-center gap-2 rounded-lg border border-[#2b3d50] bg-[#0a131e]/90 px-3 py-2 text-[10px] font-mono uppercase tracking-wide text-[#8d9cad]"><Navigation size={13} className="text-[#f4bf48]" />OpenStreetMap hazard layer <span className="ml-1 h-1.5 w-1.5 rounded-full bg-[#5ed9ad] pulse-dot" /></div><div className="absolute bottom-5 left-5 z-[400] flex gap-3 rounded-lg border border-[#2b3d50] bg-[#0a131e]/90 px-3 py-2 text-[10px] text-[#8493a3]"><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#ff756b]" />High</span><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#f4bf48]" />Medium</span><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#5ed9ad]" />Low</span></div>{!hazards.length && <div className="absolute inset-0 z-[400] flex items-center justify-center"><EmptyState icon={MapPin} title="No hazards match these filters" description="Try a broader view of the operations layer." /></div>}</div><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5"><div className="mb-3 flex items-center justify-between"><div><h2 className="text-base font-bold text-[#f2f0e9]">Signal index</h2><p className="text-xs text-[#718197]">{hazards.length} visible records</p></div><ListFilter size={17} className="text-[#708196]" /></div><div className="scrollbar-thin max-h-[455px] overflow-y-auto">{hazards.length ? hazards.map(h => <HazardRow key={h.id} hazard={h} onSelect={setSelected} />) : <EmptyState icon={Filter} title="Nothing to review" description="No saved hazards are available in this view." />}</div></div></div>}</QueryState>{selected && <HazardDrawer hazard={selected} onClose={() => setSelected(null)} />}</>;
}

function Complaints() {
  const query = useGetComplaints({ query: { queryKey: getGetComplaintsQueryKey(), refetchInterval: 60000 } });
  const create = useCreateComplaint();
  const update = useUpdateComplaint();
  const qc = useQueryClient();
  const [open, setOpen] = useState(false);
  const [reference, setReference] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [form, setForm] = useState<ComplaintInput>({ name: '', phone: '', location: '', hazardType: HazardType.Pothole, description: '', responsibleAuthority: Authority.Local_Road_Authority });
  const complaints = (query.data || []).filter(c => !statusFilter || c.status === statusFilter);
  const submit = () => create.mutate({ data: form }, { onSuccess: (data) => { setReference(data.referenceNumber); setOpen(false); setForm({ name: '', phone: '', location: '', hazardType: HazardType.Pothole, description: '', responsibleAuthority: Authority.Local_Road_Authority }); qc.invalidateQueries({ queryKey: getGetComplaintsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetAnalyticsQueryKey() }); } });
  const setField = (key: keyof ComplaintInput, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  return <><SectionHeading eyebrow="Citizen signal desk" title="Complaints" description="Review incoming reports from residents and keep every handoff visible." action={<Button onClick={() => setOpen(true)} data-testid="button-new-complaint"><Flag size={14} />New complaint</Button>} /><div className="mb-5 flex items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs text-[#718197]"><ClipboardList size={15} className="text-[#f4bf48]" />{complaints.length} complaints in view</div><select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="rounded-lg border border-[#293b4e] bg-[#111c29] px-3 py-2 text-xs text-[#cdd6df] outline-none" data-testid="select-complaint-status"><option value="">All statuses</option>{complaintStatuses.map(s => <option key={s} value={s}>{s.replace('_', ' ')}</option>)}</select></div><QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{<div className="overflow-hidden rounded-xl border border-[#1d2b3b] bg-[#0f1824]"><div className="hidden grid-cols-[1.1fr_1.4fr_1fr_.8fr_.8fr] gap-4 border-b border-[#223246] px-5 py-3 text-[10px] font-mono uppercase tracking-[.12em] text-[#687b90] sm:grid"><span>Reference</span><span>Location</span><span>Type</span><span>Status</span><span>Received</span></div>{complaints.length ? complaints.map(c => <ComplaintRow key={c.id} complaint={c} onUpdate={(next) => update.mutate({ id: c.id, data: { status: next } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetComplaintsQueryKey() }) })} />) : <EmptyState icon={ClipboardList} title="No complaints found" description="New citizen reports will appear here for triage." action={<Button onClick={() => setOpen(true)}><Flag size={13} />Submit a complaint</Button>} />}</div>}</QueryState>{open && <ComplaintModal form={form} setField={setField} pending={create.isPending} onClose={() => setOpen(false)} onSubmit={submit} />}{reference && <div className="fixed bottom-5 right-5 z-50 rounded-lg border border-[#5ed9ad]/25 bg-[#10271f] px-4 py-3 text-xs text-[#84e8bc]">Complaint {reference} submitted.</div>}</>;
}
function ComplaintRow({ complaint, onUpdate }: { complaint: Complaint; onUpdate: (status: ComplaintStatus) => void }) {
  const [expanded, setExpanded] = useState(false);
  return <div className="border-b border-[#1d2b3b] last:border-0"><button className="grid w-full grid-cols-[1.1fr_1.4fr_1fr_auto] gap-4 px-5 py-4 text-left hover:bg-[#111e2d] sm:grid-cols-[1.1fr_1.4fr_1fr_.8fr_.8fr]" onClick={() => setExpanded(v => !v)} data-testid={`button-complaint-${complaint.id}`}><div><p className="font-mono text-xs font-medium text-[#f4bf48]">{complaint.referenceNumber}</p><p className="mt-1 flex items-center gap-1 text-[11px] text-[#718197] sm:hidden"><MapPin size={11} />{complaint.location}</p></div><p className="hidden truncate text-xs text-[#bbc6d0] sm:block">{complaint.location}</p><p className="hidden text-xs text-[#a7b4c0] sm:block">{complaint.hazardType}</p><Badge className={statusClass(complaint.status)}>{complaint.status.replace('_', ' ')}</Badge><span className="hidden text-xs text-[#718197] sm:block">{dateLabel(complaint.createdAt)}</span></button>{expanded && <div className="grid gap-4 bg-[#0b141f] px-5 pb-5 pt-1 text-xs sm:grid-cols-3"><Detail label="Reported by" value={complaint.name} /><Detail label="Description" value={complaint.description} /><label className="text-[10px] font-mono uppercase tracking-wide text-[#718197]">Move to status<select value={complaint.status} onChange={e => onUpdate(e.target.value as ComplaintStatus)} className="mt-2 block w-full rounded-lg border border-[#293b4e] bg-[#111c29] px-2 py-2 text-xs font-sans normal-case tracking-normal text-[#e3e9ed] outline-none" data-testid={`select-update-complaint-${complaint.id}`}>{complaintStatuses.map(s => <option key={s} value={s}>{s.replace('_', ' ')}</option>)}</select></label></div>}</div>;
}
function ComplaintModal({ form, setField, pending, onClose, onSubmit }: { form: ComplaintInput; setField: (key: keyof ComplaintInput, value: string) => void; pending: boolean; onClose: () => void; onSubmit: () => void }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#02060b]/75 p-4" onClick={onClose}><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-xl border border-[#2a3c50] bg-[#0e1825] p-6 shadow-2xl sm:p-8" onClick={e => e.stopPropagation()}><div className="mb-6 flex justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#718197]">Citizen signal</p><h2 className="mt-2 text-xl font-bold text-[#f8f4ea]">Submit a complaint</h2></div><button onClick={onClose} className="text-[#78899b]" data-testid="button-close-complaint"><X size={19} /></button></div><div className="grid gap-4 sm:grid-cols-2">{[['name','Your name'],['phone','Phone (optional)'],['location','Location']].map(([key,label]) => <label key={key} className="text-xs font-semibold text-[#aab7c3]">{label}<input value={String(form[key as keyof ComplaintInput] || '')} onChange={e => setField(key as keyof ComplaintInput, e.target.value)} className="mt-2 w-full rounded-lg border border-[#293b4e] bg-[#0a131e] px-3 py-2.5 text-sm font-normal text-[#f0f3f4] outline-none focus:border-[#f4bf48]/60" data-testid={`input-complaint-${key}`} /></label>)}<label className="text-xs font-semibold text-[#aab7c3]">Hazard type<select value={form.hazardType} onChange={e => setField('hazardType', e.target.value)} className="mt-2 w-full rounded-lg border border-[#293b4e] bg-[#0a131e] px-3 py-2.5 text-sm font-normal text-[#f0f3f4] outline-none" data-testid="select-complaint-type">{hazardTypes.map(t => <option key={t} value={t}>{t}</option>)}</select></label><label className="text-xs font-semibold text-[#aab7c3]">Responsible authority<select value={form.responsibleAuthority} onChange={e => setField('responsibleAuthority', e.target.value)} className="mt-2 w-full rounded-lg border border-[#293b4e] bg-[#0a131e] px-3 py-2.5 text-sm font-normal text-[#f0f3f4] outline-none" data-testid="select-complaint-authority">{authorities.map(a => <option key={a} value={a}>{a}</option>)}</select></label><label className="text-xs font-semibold text-[#aab7c3] sm:col-span-2">What did you observe?<textarea value={form.description} onChange={e => setField('description', e.target.value)} rows={4} placeholder="Describe the condition, obstruction, or danger..." className="mt-2 w-full resize-none rounded-lg border border-[#293b4e] bg-[#0a131e] px-3 py-2.5 text-sm font-normal text-[#f0f3f4] outline-none placeholder:text-[#53667a] focus:border-[#f4bf48]/60" data-testid="textarea-complaint-description" /></label></div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={onClose} data-testid="button-cancel-complaint">Cancel</Button><Button disabled={pending || !form.name || !form.location || !form.description} onClick={onSubmit} data-testid="button-submit-complaint">{pending ? <Loader2 size={14} className="animate-spin" /> : <Check size={14} />}Submit report</Button></div></div></div>;
}

function Reports() {
  const query = useGetReports({ query: { queryKey: getGetReportsQueryKey(), refetchInterval: 60000 } });
  const reports = query.data || [];
  return <><SectionHeading eyebrow="Document center" title="Hazard reports" description="Printable records for handoff, inspection, and accountability." action={<Button variant="ghost" onClick={() => window.print()} data-testid="button-print-all"><Printer size={14} />Print view</Button>} /><QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{<div className="grid gap-4 lg:grid-cols-2">{reports.length ? reports.map(report => <ReportCard key={report.id} report={report} />) : <div className="lg:col-span-2 rounded-xl border border-[#1d2b3b] bg-[#0f1824]"><EmptyState icon={FileText} title="No reports generated yet" description="Reports will be created alongside saved hazard records." /></div>}</div>}</QueryState></>;
}
function ReportCard({ report }: { report: Report }) {
  return <article className="print-card group rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5 transition-colors hover:border-[#344a60] sm:p-6" data-testid={`card-report-${report.id}`}><div className="flex items-start justify-between"><div><span className="font-mono text-[10px] uppercase tracking-[.15em] text-[#f4bf48]">{report.reportNumber}</span><h2 className="mt-2 text-base font-bold text-[#e9edf0]">{report.hazard.hazardType}</h2></div><Button variant="ghost" className="no-print !px-2.5" onClick={() => { window.print(); }} data-testid={`button-print-report-${report.id}`}><Printer size={14} /></Button></div><div className="mt-5 grid grid-cols-2 gap-y-4"><Detail label="Location" value={report.hazard.location} /><Detail label="Risk" value={`${report.hazard.riskLevel} · ${report.hazard.riskScore}/100`} /><Detail label="Authority" value={report.hazard.responsibleAuthority} /><Detail label="Generated" value={dateLabel(report.generatedAt)} /></div><div className="mt-5 border-t border-[#203144] pt-4"><p className="text-xs leading-5 text-[#aebbc7]">{report.hazard.recommendedAction}</p><div className="mt-3 flex items-center justify-between"><Badge className={statusClass(report.status)}>{report.status}</Badge><span className="text-[10px] text-[#62758a]">Updated {dateLabel(report.hazard.updatedAt)}</span></div></div></article>;
}

function AnalyticsPage() {
  const query = useGetAnalytics({ query: { queryKey: getGetAnalyticsQueryKey(), refetchInterval: 60000 } });
  const data = query.data;
  return <><SectionHeading eyebrow="Live intelligence" title="Safety analytics" description="Grouped signals that help teams decide where attention is needed next." /><QueryState loading={query.isLoading} error={query.isError} onRetry={() => query.refetch()}>{data && <><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><StatCard label="Total hazards" value={data.totalHazards} detail="All saved observations" icon={Layers3} /><StatCard label="High risk" value={data.highRisk} detail="Immediate response" tone="red" icon={Siren} /><StatCard label="Medium risk" value={data.mediumRisk} detail="Needs scheduling" tone="amber" icon={AlertTriangle} /><StatCard label="Resolved" value={data.resolvedHazards} detail="Closed hazard records" tone="green" icon={Check} /><StatCard label="Open complaints" value={data.openComplaints} detail="Citizen signals" icon={ClipboardList} /></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><ChartCard title="Risk distribution" subtitle="Current share by assessed risk"><Bars points={data.riskDistribution} colors={['#ff756b','#f4bf48','#5ed9ad']} /></ChartCard><ChartCard title="Hazard types" subtitle="What teams are seeing most"><Bars points={data.hazardTypeDistribution} colors={['#f4bf48','#57c7d8','#a68af2','#5ed9ad']} /></ChartCard><ChartCard title="Hazards over time" subtitle="New records by reporting period"><Bars points={data.hazardsOverTime} colors={['#f4bf48']} /></ChartCard><ChartCard title="Authority workload" subtitle="Records by responsible authority"><Bars points={data.authorityDistribution} colors={['#57c7d8','#f4bf48','#5ed9ad']} /></ChartCard></div><div className="mt-6"><ChartCard title="Complaint status" subtitle="Where citizen reports sit in the response cycle"><Bars points={data.complaintStatus} colors={['#f4bf48','#57c7d8','#5ed9ad','#ff756b']} horizontal /></ChartCard></div></>}</QueryState></>;
}
function ChartCard({ title, subtitle, children }: { title: string; subtitle: string; children: React.ReactNode }) { return <section className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-5 sm:p-6"><div className="mb-6"><h2 className="text-base font-bold text-[#f2f0e9]">{title}</h2><p className="mt-1 text-xs text-[#718197]">{subtitle}</p></div>{children}</section>; }
function Bars({ points, colors, horizontal = false }: { points: { label: string; count: number }[]; colors: string[]; horizontal?: boolean }) { const max = Math.max(...points.map(p => p.count), 1); if (!points.length) return <div className="py-8 text-center text-xs text-[#718197]">No grouped data available.</div>; return <div className={cn('space-y-4', horizontal && 'grid gap-x-8 gap-y-4 md:grid-cols-2')}>{points.map((point, i) => <div key={`${point.label}-${i}`} data-testid={`bar-${point.label}`}><div className="mb-1.5 flex justify-between gap-3 text-xs"><span className="truncate text-[#a9b6c1]">{point.label}</span><span className="font-mono text-[#e3e8eb]">{point.count}</span></div><div className="h-2 overflow-hidden rounded-full bg-[#1b2a3a]"><div className="h-full rounded-full transition-all duration-700" style={{ width: `${(point.count / max) * 100}%`, backgroundColor: colors[i % colors.length] }} /></div></div>)}</div>; }

function About() {
  const seed = useSeedDemoData();
  const clear = useClearDemoData();
  const qc = useQueryClient();
  const runSeed = () => seed.mutate(undefined, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetHazardsQueryKey() }); qc.invalidateQueries({ queryKey: getGetComplaintsQueryKey() }); qc.invalidateQueries({ queryKey: getGetReportsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAnalyticsQueryKey() }); } });
  const runClear = () => { if (window.confirm('Clear all demo records?')) clear.mutate(undefined, { onSuccess: () => { qc.invalidateQueries(); } }); };
  return <><SectionHeading eyebrow="RoadGuard brief" title="Make the next safe move obvious" description="RoadGuard connects visual road evidence, citizen reports, and local response into one shared operating picture." /><div className="grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><div className="overflow-hidden rounded-xl border border-[#1d2b3b] bg-[#0f1824]"><div className="relative min-h-[250px] overflow-hidden border-b border-[#223246] bg-[#0b131d] p-7 sm:p-10"><div className="absolute -right-16 -top-20 h-72 w-72 rounded-full border border-[#f4bf48]/15" /><div className="absolute -right-4 -top-8 h-48 w-48 rounded-full border border-[#f4bf48]/10" /><div className="absolute bottom-0 left-0 h-px w-[68%] bg-[#f4bf48]/70" /><div className="relative max-w-lg"><Badge className="border-[#f4bf48]/30 text-[#f4bf48]"><Shield size={11} className="mr-1" />Built for civic response</Badge><h2 className="mt-5 text-3xl font-extrabold leading-tight tracking-[-.05em] text-[#f8f4ea] sm:text-4xl">From sighting to street crew, without the blind spots.</h2><p className="mt-4 max-w-md text-sm leading-6 text-[#8796a7]">Every record keeps its evidence, risk context, recommended action, and accountable authority together.</p></div></div><div className="grid gap-5 p-6 sm:grid-cols-3"><Step number="01" title="Capture" text="Upload an image or receive a citizen complaint." icon={Camera} /><Step number="02" title="Assess" text="Development analysis turns evidence into a risk signal." icon={Activity} /><Step number="03" title="Respond" text="Route the next action and keep status visible." icon={Navigation} /></div></div><div className="space-y-6"><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-6"><div className="mb-5 flex items-center gap-3"><span className="rounded-lg bg-[#57c7d8]/10 p-2 text-[#57c7d8]"><Info size={17} /></span><div><h2 className="text-base font-bold text-[#f2f0e9]">Reading the output</h2><p className="text-xs text-[#718197]">A practical vocabulary</p></div></div><div className="space-y-4"><Definition title="Risk score" text="A 0–100 prioritization signal. It helps teams sequence work; it is not a legal or engineering certification." /><Definition title="Damage percentage" text="An estimate of visible surface damage in the submitted view." /><Definition title="Recommended action" text="The next operational step suggested by the assessment." /></div></div><div className="rounded-xl border border-[#1d2b3b] bg-[#0f1824] p-6"><div className="mb-4 flex items-center gap-3"><Building2 size={17} className="text-[#f4bf48]" /><div><h2 className="text-base font-bold text-[#f2f0e9]">Demo workspace</h2><p className="text-xs text-[#718197]">Use labelled records to explore the console</p></div></div><div className="flex flex-wrap gap-2"><Button onClick={runSeed} disabled={seed.isPending} data-testid="button-seed-demo">{seed.isPending ? <Loader2 size={14} className="animate-spin" /> : <Zap size={14} />}Seed demo records</Button><Button variant="danger" onClick={runClear} disabled={clear.isPending} data-testid="button-clear-demo">{clear.isPending ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />}Clear demo records</Button></div></div></div></div></>;
}
function Step({ number, title, text, icon: Icon }: { number: string; title: string; text: string; icon: React.ElementType }) { return <div><div className="mb-3 flex items-center gap-2"><span className="font-mono text-[10px] text-[#f4bf48]">{number}</span><Icon size={14} className="text-[#6f8297]" /></div><h3 className="text-sm font-bold text-[#dfe6ea]">{title}</h3><p className="mt-1.5 text-xs leading-5 text-[#718197]">{text}</p></div>; }
function Definition({ title, text }: { title: string; text: string }) { return <div className="border-l-2 border-[#f4bf48]/50 pl-3"><h3 className="text-xs font-bold text-[#dce3e8]">{title}</h3><p className="mt-1 text-xs leading-5 text-[#7e8ea0]">{text}</p></div>; }

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Shell><Switch><Route path="/" component={Dashboard} /><Route path="/analyze" component={Analyze} /><Route path="/map" component={MapPage} /><Route path="/complaints" component={Complaints} /><Route path="/reports" component={Reports} /><Route path="/analytics" component={AnalyticsPage} /><Route path="/about" component={About} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;